const main=document.querySelector('main'),nav=document.querySelector('nav');const t=k=>ui[language][k];const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const persist=(key,v)=>{try{localStorage.setItem(key,JSON.stringify(v))}catch{}};const ext=(url,label)=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
function shell(){document.documentElement.lang=language;document.querySelector('.brand').textContent=language==='ru'?'Линейное письмо Б':'Linear B reader';nav.innerHTML=[['/','catalogue'],['/signs','signs'],['/sources','sources']].map(([path,key])=>`<a href="#${path}" ${route()===path?'aria-current="page"':''}>${t(key)}</a>`).join('');document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===language)));document.querySelector('#footer-note').textContent=t('footer');document.querySelector('#footer-link').textContent=t('about');document.querySelector('.skip').textContent=language==='ru'?'К содержимому':'Skip to content'}
function route(){return (location.hash.slice(1)||'/').split('?')[0]}
function announce(s){document.querySelector('#announce').textContent=s}
function glyphs(word){return partsOf(word||'').map(v=>signInfo(v).number?signInfo(v).glyph:'').join('')}
function catalogue(){main.innerHTML=`<div class="intro"><div><h1>${t('heading')}</h1><p>${t('intro')}</p></div><p class="scope">${t('corpus')}</p></div><p class="argos-note">${t('argosNote')} ${ext(argosSource,'Hall 2024, p. 15 →')}</p><div class="toolbar"><label class="field search">${t('search')}<input id="search" type="search" value="${escape(query)}" autocomplete="off"></label><label class="field">${t('location')}<select id="site"><option value="">${t('allSites')}</option>${[...new Set(tablets.map(d=>d.site))].map(v=>`<option value="${v}" ${siteFilter===v?'selected':''}>${t(v)}</option>`).join('')}</select></label><label class="field">${t('topic')}<select id="topic"><option value="">${t('all')}</option>${[...new Set(tablets.map(d=>d.topic))].map(v=>`<option value="${v}" ${topic===v?'selected':''}>${t(v)}</option>`).join('')}</select></label><label class="field"><span><input type="checkbox" id="saved-only" ${savedOnly?'checked':''}> ${t('readingList')}</span></label></div><p class="result-count" role="status"></p><div class="catalogue" id="records"></div>`;updateRecords();document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;updateRecords()});document.querySelector('#site').addEventListener('change',e=>{siteFilter=e.target.value;updateRecords()});document.querySelector('#topic').addEventListener('change',e=>{topic=e.target.value;updateRecords()});document.querySelector('#saved-only').addEventListener('change',e=>{savedOnly=e.target.checked;updateRecords()})}
function updateRecords(){const q=normalise(query.toLowerCase().trim());const rows=tablets.filter(d=>(!topic||d.topic===topic)&&(!siteFilter||d.site===siteFilter)&&(!savedOnly||saved.includes(d.id))&&normalise(`${d.code} ${d.edition||''} ${d.lines.map(l=>l.text).join(' ')} ${d.title.en} ${d.title.ru} ${t(d.site)} ${t(d.topic)}`.toLowerCase()).includes(q));document.querySelector('.result-count').textContent=`${rows.length} / ${tablets.length} · ${t('results')}`;document.querySelector('#records').innerHTML=rows.length?rows.map(d=>`<a class="catalogue-row" href="#/tablet/${d.id}"><div class="mini" aria-hidden="true"><img src="assets/tablet.svg" alt=""><span class="glyphs">${glyphs(d.words[0]).slice(0,8)}</span></div><div><h2 class="record-title">${d.code}</h2><p class="row-sub">${d.title[language]}</p><p class="scope">${t('lines')}: ${d.lines.length} · ${t('words')}: ${d.words.length}</p></div><div class="row-note">${t(d.site)} · ${d.period}<br>${t(d.topic)}<br>${t('open')} →</div></a>`).join(''):`<div class="empty"><p>${savedOnly&&!saved.length?t('noSaved'):t('empty')}</p><button class="text-button" id="clear">${t('clear')}</button></div>`;document.querySelector('#clear')?.addEventListener('click',()=>{query='';topic='';siteFilter='';savedOnly=false;catalogue()})}
function tablet(d){
 currentId=d.id;const word=d.words[wordIndex]||'',parts=partsOf(word),s=signInfo(parts[signIndex]||'');
 const transcript=d.lines.map(line=>`<div class="text-line"><span class="line-label">${escape(line.label)}</span><div class="line-tokens">${line.tokens.map(token=>token.entry?`<button type="button" class="line-word" data-word="${token.entry.index}" aria-pressed="${token.entry.index===wordIndex}">${escape(token.raw)}</button>`:escape(token.raw).replaceAll('VAS','<sup>VAS</sup>')).join('')}</div></div>`).join('');
 main.innerHTML=`<a class="back" href="#/">← ${t('back')}</a><div class="record-heading"><div><h1>${d.code}</h1><p>${d.title[language]} · ${d.edition||d.code}</p></div><p>${t(d.site)} · ${d.period}<br>${t('lines')}: ${d.lines.length} · ${t('words')}: ${d.words.length}</p></div>${renderStudy(d,language)}<div class="workspace"><figure class="artifact full-artifact"><p class="word-caption">${t('wholeText')}</p>${renderDrawing(d,wordIndex,signIndex)}<figcaption>${t('caption')}</figcaption><p class="scope">${t('drawingLegend')}</p></figure><aside class="inspector"><h2>${t('selected')}</h2><div class="sign-name"><span class="phonetic">${escape(s.value)}</span><span class="catalogue-number">${s.numeric?'':s.number?'*'+s.number:'—'}</span></div><dl><div><dt>${t('type')}</dt><dd class="selected-type">${t(s.numeric?'numericSign':s.number?'syllabogram':'unknownSign')}</dd></div><div><dt>Unicode</dt><dd class="selected-code">${s.code}</dd></div><div><dt>${t('position')}</dt><dd class="selected-position">${signIndex+1} / ${parts.length}</dd></div></dl><p>${t('hint')}</p><a class="show-reading" ${bySign[s.value]?'':'hidden'} href="#/sign/${s.value}">${t('signs')}: ${escape(s.value)} →</a></aside><section class="reading"><h2>${t('fullText')}</h2><p class="notice">${t('normalisation')}</p><div class="text-lines">${transcript}</div><details class="transcription-legend"><summary>${language==='ru'?'Условные обозначения':'Editorial conventions'}</summary><p>${t('legend')}</p></details>${d.fullEdition?`<section class="full-interpretation"><h2>${t('editionHeading')}</h2><p class="notice">${t('editionNote')}</p>${renderEditionRows(d.fullEdition.interpretation,'grc-Latn')}<p class="citation">${ext(d.fullEdition.source,d.fullEdition.citation)}</p></section>`:d.interpretation?`<p class="interpretation">${t('interpretation')} (${t('line')} ${d.line}):<br><i lang="grc-Latn">${d.interpretation}</i></p>`:''}</section><section class="translation"><h2>${t('translation')}</h2>${d.fullEdition?`${renderEditionRows(d.fullEdition.translation,'en')}<p class="citation">${t('editionScope')}</p>`:d.translation?`<blockquote lang="en">“${d.translation}”</blockquote><p class="citation">${t('translationShort')}</p>`:''}${d.translationURL?`<p>${ext(d.translationURL,t('translationExternal')+' →')}</p><p class="citation">${d.translationCitation}</p>`:`<p class="notice">${t('translationMissing')}</p>`}</section></div><div class="notes"><section><h2>${t('context')}</h2><p>${d.context[language]}</p><dl class="provenance"><div><dt>${t('findspot')}</dt><dd>${escape(d.findspot)}</dd></div><div><dt>${t('scribe')}</dt><dd>${d.scribe}</dd></div><div><dt>${t('period')}</dt><dd>${d.period}</dd></div><div><dt>${t('museum')}</dt><dd>${escape(d.inventory)}</dd></div></dl>${d.parallel?`<h3 style="margin-top:24px">${t('parallel')}</h3><p><i>${d.parallel.myc}</i> — <i>${d.parallel.later}</i></p><p class="scope">${d.parallel[language]}</p>`:''}<details><summary>${t('editorial')}</summary><p>${t('editorialText')}</p></details></section><section><h2>${t('sourceOfText')}</h2><p>${ext(d.source,'LiBER · '+d.code)}</p><p class="scope">Del Freo, Di Filippo & Rougemont (2024)<br>CNR Edizioni · ${t('sourceDate')}</p><div class="actions"><button type="button" class="text-button" id="save" aria-pressed="${saved.includes(d.id)}">${saved.includes(d.id)?t('saved'):t('save')}</button><button type="button" class="text-button" id="copy">${t('copy')}</button><button type="button" class="text-button" id="copy-reading">${t('copyReading')}</button></div><p id="copy-status" class="scope" role="status"></p></section></div>`;
 const updateStudy=bindStudy(d,language,w=>select(w,0));updateStudy(wordIndex);
 const updateURL=()=>history.replaceState(null,'','#'+tabletRoute(d.id,wordIndex,signIndex));
 function inspect(w,index,preview=false){const ps=partsOf(d.words[w]||''),item=signInfo(ps[index]||'');document.querySelector('.inspector h2').textContent=t(preview?'preview':'selected');document.querySelector('.phonetic').textContent=item.value;document.querySelector('.catalogue-number').textContent=item.numeric?'':item.number?'*'+item.number:'—';document.querySelector('.selected-type').textContent=t(item.numeric?'numericSign':item.number?'syllabogram':'unknownSign');document.querySelector('.selected-code').textContent=item.code;document.querySelector('.selected-position').textContent=d.words.length?`${index+1} / ${ps.length}`:'—';const link=document.querySelector('.inspector .show-reading');link.hidden=!bySign[item.value];link.href='#/sign/'+item.value;link.textContent=t('signs')+': '+item.value+' →'}
 function select(w,index,focus=false){wordIndex=w;signIndex=index;updateURL();updateStudy(w);document.querySelectorAll('[data-glyph-word]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.glyphWord===w&&+b.dataset.index===index)));document.querySelectorAll('[data-word]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.word===w)));inspect(w,index);if(focus)document.querySelector(`[data-glyph-word="${w}"][data-index="${index}"]`)?.focus({preventScroll:true});announce(d.words[w]+' · '+partsOf(d.words[w])[index])}
 document.querySelectorAll('[data-glyph-word]').forEach(b=>{const w=+b.dataset.glyphWord,index=+b.dataset.index;b.addEventListener('click',()=>select(w,index));b.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')inspect(w,index,true)});b.addEventListener('pointerleave',()=>inspect(wordIndex,signIndex));b.addEventListener('focus',()=>inspect(w,index,w!==wordIndex||index!==signIndex));b.addEventListener('blur',()=>inspect(wordIndex,signIndex));b.addEventListener('keydown',e=>{const next=nextSign(index,e.key,partsOf(d.words[w]).length);if(next!==null){e.preventDefault();select(w,next,true)}})});
 document.querySelectorAll('[data-word]').forEach(b=>b.addEventListener('click',()=>{select(+b.dataset.word,0,true);document.querySelector(`[data-glyph-word="${wordIndex}"]`)?.scrollIntoView({block:'center',inline:'nearest',behavior:'auto'})}));
 if(!d.words.length){document.querySelector('.inspector').innerHTML=`<h2>${t('survivingTraces')}</h2><p>${t('noSyllables')}</p>`}
 document.querySelector('#save').addEventListener('click',e=>{saved=saved.includes(d.id)?saved.filter(id=>id!==d.id):[...saved,d.id];persist('lb.saved',saved);e.currentTarget.textContent=saved.includes(d.id)?t('saved'):t('save');e.currentTarget.setAttribute('aria-pressed',String(saved.includes(d.id)))});
 document.querySelector('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(`Del Freo, M., Di Filippo, F., Rougemont, F. (2024). LiBER: ${d.code}, line ${d.entries[wordIndex]?.line||'—'}. ${d.source} (accessed 2026-10-31).`);document.querySelector('#copy-status').textContent=t('copied')}catch{document.querySelector('#copy-status').textContent=d.source}});
 document.querySelector('#copy-reading').addEventListener('click',async()=>{updateURL();try{await navigator.clipboard.writeText(location.href);document.querySelector('#copy-status').textContent=t('readingCopied')}catch{document.querySelector('#copy-status').textContent=location.href}});
}
function signList(){main.innerHTML=`<div class="intro"><div><h1>${t('signs')}</h1><p>${t('signIntro')}</p></div><p class="scope">${ext('https://www.unicode.org/charts/PDF/U10000.pdf','Unicode · U+10000–U+1007F')}</p></div><label class="field search">${t('signSearch')}<input type="search" id="sign-search" value="${escape(signQuery)}" autocomplete="off"></label><p class="notice" id="sign-count" role="status"></p><div class="sign-grid"></div>`;updateSigns();document.querySelector('#sign-search').addEventListener('input',e=>{signQuery=e.target.value;updateSigns()})}
function updateSigns(){const q=signQuery.toLowerCase().trim();const rows=signs.filter(s=>`${s.value} ${s.number} ${s.code}`.toLowerCase().includes(q));document.querySelector('#sign-count').textContent=`${rows.length} / ${signs.length} · ${t('signCount')}`;document.querySelector('.sign-grid').innerHTML=rows.length?rows.map(s=>`<a class="sign-tile" href="#/sign/${s.value}" aria-label="${s.value}, ${t('syllabogram')} ${s.number}"><span class="glyph" aria-hidden="true">${s.glyph}</span><span>${s.value}</span><small>*${s.number}</small></a>`).join(''):`<p class="empty">${t('empty')}</p>`}
function signDetail(s){const occurrences=tablets.filter(d=>d.words.some(w=>partsOf(w).map(v=>signInfo(v).value).includes(s.value)));main.innerHTML=`<a class="back" href="#/signs">← ${t('signs')}</a><div class="content-column"><h1 style="margin-top:24px">${s.value} · *${s.number}</h1><div class="big-glyph" aria-hidden="true">${s.glyph}</div><p>${s.code} · ${t('syllabogram')}</p><p class="scope">${t('signSource')} ${ext('https://www.unicode.org/charts/PDF/U10000.pdf','Unicode')}</p><h2>${t('occurrences')}</h2>${occurrences.length?occurrences.map(d=>`<p>${d.code} · ${d.words.flatMap((w,i)=>partsOf(w).map(v=>signInfo(v).value).includes(s.value)?[`<a href="#${tabletRoute(d.id,i,partsOf(w).map(v=>signInfo(v).value).indexOf(s.value))}">${w}</a>`]:[]).join(', ')}</p>`).join(''):`<p>${t('noOccurrences')}</p>`}</div>`}
function sources(){main.innerHTML=`<div class="content-column"><h1>${t('sources')}</h1><h2>${t('used')}</h2><section class="reference"><h3>${ext('https://liber.cnr.it','LiBER — Linear B Electronic Resources')}</h3><p>Del Freo, M., Di Filippo, F. & Rougemont, F. (2024). CNR Edizioni. ISBN 978-88-8080-690-5.</p><p class="scope">${t('normalisation')}</p>${tablets.map(d=>`<p>${ext(d.source,d.code)}</p>`).join('')}</section><section class="reference"><h3>${ext(translationPDF,'Thomas G. Palaima — Linear B Sources')}</h3><p>2004 · Appendix One, Anthology of Classical Myth, pp. 439–454. Hackett.</p><p class="scope">${t('translationShort')} ${t('sourceDate')}</p></section><section class="reference"><h3>${ext(sourceURL,'Mnamon — Linear B')}</h3><p>Scuola Normale Superiore · ${t('sourceSection')}</p><small>PY Ta 709, PY An 657 · ${t('accessed')}</small><p class="scope">${t('photo')}</p></section><section class="reference"><h3>${ext('https://www.unicode.org/charts/PDF/U10000.pdf',t('unicode'))}</h3><p>Unicode Consortium · U+10000–U+1007F</p><small>${t('signSource')}</small></section><section class="reference"><h3>${ext(argosSource,'Jonathan M. Hall — Argos')}</h3><p>2024 · The Oxford History of the Archaic Greek World, I. Ed. Paul Cartledge &amp; Paul Christesen. Oxford University Press, p. 15 (PDF p. 54).</p><p>${t('argosNote')}</p></section><section class="reference"><h3>Unicode · ideograms and numbers</h3><p>${ext('https://www.unicode.org/charts/PDF/U10080.pdf','Linear B Ideograms')} · ${ext('https://www.unicode.org/charts/PDF/U10100.pdf','Aegean Numbers')}</p></section>${scholarlySources.map(r=>`<section class="reference"><h3>${ext(r.url,r.title)}</h3><p>${r.detail}</p></section>`).join('')}<h2>${t('further')}</h2><p class="scope">${t('furtherNote')} ${ext(bibliographyURL,'Mnamon · Bibliography')}</p>${books.map(b=>`<section class="reference"><h3><i>${b.title}</i></h3><p>${b.author} · ${b.year}</p><small>${b.detail}</small></section>`).join('')}</div>`}
function about(){main.innerHTML=`<div class="content-column"><h1>${t('policyTitle')}</h1><p>${t('policyIntro')}</p>${[1,2,3,4].map(i=>`<h2>${t('policy'+i)}</h2><p>${t('policy'+i+'Text')}</p>`).join('')}<button class="text-button" id="reset">${t('reset')}</button><p class="scope">Fonts: ${ext('https://fonts.google.com/specimen/Old+Standard+TT','Old Standard TT')}, ${ext('https://fonts.google.com/noto/specimen/Noto+Sans+Linear+B','Noto Sans Linear B')}, ${ext('https://fonts.google.com/noto/specimen/Noto+Serif','Noto Serif')}. SIL Open Font License.</p></div>`;document.querySelector('#reset').addEventListener('click',()=>{saved=[];persist('lb.saved',saved);announce(t('resetDone'))})}
function render(){shell();const path=route();document.title='Linear B Reader';if(path==='/')catalogue();else if(path==='/signs')signList();else if(path==='/sources')sources();else if(path==='/about')about();else if(path.startsWith('/tablet/')&&tablets.find(d=>d.id===path.slice(8))){const d=tablets.find(d=>d.id===path.slice(8));document.title=d.code+' · Linear B Reader';const selected=readSelection(location.hash,d.words);wordIndex=selected.word;signIndex=selected.sign;tablet(d)}else if(path.startsWith('/sign/')&&bySign[path.slice(6)])signDetail(bySign[path.slice(6)]);else main.innerHTML=`<h1>${t('unknown')}</h1><p class="notice">${t('unknownText')}</p><a class="show-reading" href="#/">${t('back')}</a>`}
document.querySelectorAll('[data-language]').forEach(b=>b.addEventListener('click',()=>{language=b.dataset.language;persist('lb.language',language);render()}));window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);main.focus({preventScroll:true})});render();

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView()});
